    static JSONObject export(Store store){try{Map<Long,JSONObject> nights=new HashMap<>();for(JSONObject row:store.rows("SELECT * FROM sessions WHERE end IS NOT NULL"))nights.put(row.getLong("id"),row);JSONArray runs=new JSONArray(),requests=new JSONArray();Set<String> included=new HashSet<>();long omitted=0;List<JSONObject> all=store.rows("SELECT * FROM dream_cue_runs ORDER BY created LIMIT 10001");if(all.size()>10000)throw new IllegalArgumentException("Timed cue history exceeds the backup limit.");for(JSONObject row:all){row.remove("local_owner");if(!nights.containsKey(row.getLong("session"))){omitted++;continue;}runs.put(row);included.add(row.getString("nonce"));}List<JSONObject> events=store.rows("SELECT * FROM dream_cue_requests ORDER BY nonce,ordinal LIMIT 60001");if(events.size()>60000)throw new IllegalArgumentException("Timed cue history exceeds the backup limit.");for(JSONObject row:events)if(included.contains(row.getString("nonce")))requests.put(row);JSONObject value=new JSONObject().put("dream_export_scope","ended_recordings_only").put("omitted_active",omitted).put("runs",runs).put("requests",requests);validate(new JSONObject().put("dream_cues",value),nights);return value;}catch(JSONException invalid){throw new IllegalArgumentException("Timed-cue history needs review before backup.",invalid);}}
